-- Nexmark qhop on flink, KAFKA-SINK sink variant. NOT a nexmark query. Bids
-- per auction per 10s window sliding every 2s, so each bid lands in five
-- overlapping panes. HOP's only nexmark query is q5, whose top-1 rank makes
-- it a changelog the row-count gate cannot carry. NOTE the argument orders
-- differ and are NOT interchangeable: clink is HOP(time, SIZE, SLIDE),
-- Flink's table function is HOP(TABLE, DESCRIPTOR, SLIDE, SIZE).
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-qhop-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_qhop (`auction` BIGINT, `num` BIGINT) WITH (
  'connector' = 'kafka',
  'topic' = '__OUT__',
  'properties.bootstrap.servers' = 'kafka:29092',
  'format' = 'json',
  'sink.delivery-guarantee' = 'at-least-once'
);
INSERT INTO sink_qhop
SELECT auction, COUNT(*) AS num FROM TABLE(HOP(TABLE bid, DESCRIPTOR(ts), INTERVAL '2' SECOND, INTERVAL '10' SECOND)) GROUP BY window_start, window_end, auction;
